// TestRenderBeaconState gates Render against the checked-in golden, proving the
// output for a realistic type stays stable. The golden is gofmt-normalized
// before comparison. Run with -update to regenerate it from current Render
// output.
func TestRenderBeaconState(t *testing.T) {
	got, err := Render("github.com/prysmaticlabs/prysm/v3/proto/beacon/p2p/v1", "", []gentypes.ValRep{testFixBeaconState})
	if err != nil {
		t.Fatalf("render.Render: %v", err)
	}

	golden := filepath.Join("testdata", "beacon_state.ssz.go.expected")
	if *update {
		if err := os.WriteFile(golden, got, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	raw, err := os.ReadFile(golden)
	if err != nil {
		t.Fatal(err)
	}
	want, err := format.Source(raw)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != string(want) {
		t.Fatalf("Render output differs from golden %s (run with -update if the change is intended):\n--- want ---\n%s\n--- got ---\n%s", golden, want, got)
	}
}
